1	package darksafe
2	
3	import (
4		"reflect"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// This file covers the optional firstBatchSize setting: batch 1 is capped at
11	// firstBatchSize while every later batch keeps the batchSize cap. The setting
12	// is only a cap — selection (disabled/include/exclude) is decided exactly as
13	// before, fault-domain spreading still defers conflicting clusters, every
14	// selected cluster appears in exactly one batch, and no empty batch is ever
15	// emitted. Omitting the field or setting it equal to batchSize must reproduce
16	// the original plan byte-for-byte.
17	
18	// firstBatchDoc builds a plan document with the given batch capacity and
19	// cluster list; first is substituted as a raw JSON literal (use "" to omit
20	// the field entirely).
21	func firstBatchDoc(batchSize int, first string, clusters string) string {
22		doc := `{"app":"app","revision":"r1","image":"img","batchSize":` +
23			strconv.Itoa(batchSize)
24		if first != "" {
25			doc += `,"firstBatchSize":` + first
26		}
27		return doc + `,"clusters":[` + clusters + `]}`
28	}
29	
30	// TestPlan_FirstBatchSpreadByThenFullCapacity is the contract example: a
31	// smaller first batch under fault-domain spreading, with later batches back
32	// at the full batchSize capacity. a,b are east; c,e west; d north. Batch 1 is
33	// capped at 2: a takes east, b conflicts and is deferred, c (west) still
34	// joins. Batch 2 runs at capacity 3 again — b, d and e all fit — proving the
35	// first-batch cap does not stick to later batches.
36	func TestPlan_FirstBatchSpreadByThenFullCapacity(t *testing.T) {
37		in := parsePlan(t, `{
38			"app": "app", "revision": "r1", "image": "img",
39			"batchSize": 3, "firstBatchSize": 2, "spreadBy": "zone",
40			"clusters": [
41				{"id": "a", "tags": {"zone": "east"}},
42				{"id": "b", "tags": {"zone": "east"}},
43				{"id": "c", "tags": {"zone": "west"}},
44				{"id": "d", "tags": {"zone": "north"}},
45				{"id": "e", "tags": {"zone": "west"}}
46			]
47		}`)
48		plan, err := MakeReleasePlan(in)
49		if err != nil {
50			t.Fatal(err)
51		}
52		if got := batchIDs(plan); strings.Join(got, "|") != "a,c|b,d,e" {
53			t.Fatalf("batches = %v, want [a c]|[b d e]", got)
54		}
55		for i, b := range plan.Batches {
56			if b.Index != i+1 {
57				t.Fatalf("batch %d has index %d, want %d", i, b.Index, i+1)
58			}
59		}
60		// Every selected cluster appears exactly once across the plan.
61		seen := map[string]int{}
62		for _, b := range plan.Batches {
63			for _, id := range b.Clusters {
64				seen[id]++
65			}
66		}
67		for _, id := range []string{"a", "b", "c", "d", "e"} {
68			if seen[id] != 1 {
69				t.Fatalf("cluster %q appears %d times, want exactly 1", id, seen[id])
70			}
71		}
72	}
73	
74	// TestPlan_FirstBatchPlainChunking covers ordinary batching without spreadBy:
75	// batch 1 closes at the first-batch cap, batch 2 regains the full batchSize
76	// capacity, and the tail batch closes short.
77	func TestPlan_FirstBatchPlainChunking(t *testing.T) {
78		in := parsePlan(t, firstBatchDoc(3, "2",
79			`{"id":"c1"},{"id":"c2"},{"id":"c3"},{"id":"c4"},{"id":"c5"},{"id":"c6"},{"id":"c7"}`))
80		plan, err := MakeReleasePlan(in)
81		if err != nil {
82			t.Fatal(err)
83		}
84		if got := batchIDs(plan); strings.Join(got, "|") != "c1,c2|c3,c4,c5|c6,c7" {
85			t.Fatalf("batches = %v, want [c1 c2]|[c3 c4 c5]|[c6 c7]", got)
86		}
87	}
88	
89	// TestPlan_FirstBatchUnsetOrEqualMatchesOriginal requires three spellings of
90	// "no separate first batch" — field absent, Go zero value, and an explicit
91	// value equal to batchSize — to produce exactly the original plan: same batch
92	// numbering, same cluster order, same excluded list with reasons.
93	func TestPlan_FirstBatchUnsetOrEqualMatchesOriginal(t *testing.T) {
94		clusters := `{"id":"c1"},{"id":"c2","disabled":true},{"id":"c3"},{"id":"c4"},{"id":"c5"}`
95		base := parsePlan(t, firstBatchDoc(2, "", clusters))
96		equal := parsePlan(t, firstBatchDoc(2, "2", clusters))
97		if equal.FirstBatchSize != 2 {
98			t.Fatalf("parsed firstBatchSize = %d, want 2", equal.FirstBatchSize)
99		}
100		if base.FirstBatchSize != 0 {
101			t.Fatalf("absent firstBatchSize must parse as 0 (unset), got %d", base.FirstBatchSize)
102		}
103	
104		planBase, err := MakeReleasePlan(base)
105		if err != nil {
106			t.Fatal(err)
107		}
108		planEqual, err := MakeReleasePlan(equal)
109		if err != nil {
110			t.Fatal(err)
111		}
112		if !reflect.DeepEqual(planBase, planEqual) {
113			t.Fatalf("firstBatchSize == batchSize changed the plan:\n base:  %+v\n equal: %+v", planBase, planEqual)
114		}
115	
116		// The Go zero value (unset) must agree with both.
117		goIn := base
118		goIn.FirstBatchSize = 0
119		planGo, err := MakeReleasePlan(goIn)
120		if err != nil {
121			t.Fatal(err)
122		}
123		if !reflect.DeepEqual(planBase, planGo) {
124			t.Fatalf("Go zero firstBatchSize changed the plan:\n base: %+v\n go:   %+v", planBase, planGo)
125		}
126	
127		if got := batchIDs(planBase); strings.Join(got, "|") != "c1,c3|c4,c5" {
128			t.Fatalf("original batching changed: %v", got)
129		}
130		if len(planBase.Excluded) != 1 ||
131			planBase.Excluded[0] != (ExcludedCluster{ID: "c2", Reason: ReasonDisabled}) {
132			t.Fatalf("excluded = %+v, want c2: %s", planBase.Excluded, ReasonDisabled)
133		}
134	}
135	
136	// TestPlan_FirstBatchSingleCluster: one selected cluster yields exactly one
137	// batch, however the caps are set.
138	func TestPlan_FirstBatchSingleCluster(t *testing.T) {
139		in := parsePlan(t, firstBatchDoc(3, "2", `{"id":"only"}`))
140		plan, err := MakeReleasePlan(in)
141		if err != nil {
142			t.Fatal(err)
143		}
144		if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "only" {
145			t.Fatalf("expected one batch [only], got %+v", plan.Batches)
146		}
147		if plan.Batches[0].Index != 1 {
148			t.Fatalf("batch index = %d, want 1", plan.Batches[0].Index)
149		}
150	}
151	
152	// TestPlan_FirstBatchCapIsOnlyAnUpperBound: the first batch may close short —
153	// when fewer clusters are selected than the cap allows, and when fault-domain
154	// conflicts leave no cluster that can still enter it. No empty batch is ever
155	// emitted in either case.
156	func TestPlan_FirstBatchCapIsOnlyAnUpperBound(t *testing.T) {
157		// Fewer selected clusters than the first-batch cap: one short batch only.
158		in := parsePlan(t, firstBatchDoc(3, "2", `{"id":"c1"}`))
159		plan, err := MakeReleasePlan(in)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if len(plan.Batches) != 1 || len(plan.Batches[0].Clusters) != 1 {
164			t.Fatalf("short selection must close batch 1 short without empty batches, got %+v", plan.Batches)
165		}
166	
167		// Domain conflicts: batch 1 (cap 2) takes a(east) and c(west); b and d
168		// conflict and are deferred. Batch 2 at capacity 3 takes b(east) and
169		// d(north) — e(west) conflicts with nothing left but still fits. The
170		// domain limit is never relaxed to fill a batch.
171		in = parsePlan(t, `{
172			"app": "app", "revision": "r1", "image": "img",
173			"batchSize": 3, "firstBatchSize": 2, "spreadBy": "zone",
174			"clusters": [
175				{"id": "a", "tags": {"zone": "east"}},
176				{"id": "b", "tags": {"zone": "east"}},
177				{"id": "c", "tags": {"zone": "west"}}
178			]
179		}`)
180		plan, err = MakeReleasePlan(in)
181		if err != nil {
182			t.Fatal(err)
183		}
184		if got := batchIDs(plan); strings.Join(got, "|") != "a,c|b" {
185			t.Fatalf("batches = %v, want [a c]|[b] (domain limit never relaxed)", got)
186		}
187		for _, b := range plan.Batches {
188			if len(b.Clusters) == 0 {
189				t.Fatalf("plan contains an empty batch: %+v", plan.Batches)
190			}
191		}
192	}
193	
194	// TestPlan_FirstBatchDoesNotChangeSelection: disabled/include/exclude decide
195	// the selected set exactly as without the setting; the first-batch cap only
196	// splits that set differently.
197	func TestPlan_FirstBatchDoesNotChangeSelection(t *testing.T) {
198		in := parsePlan(t, `{
199			"app": "app", "revision": "r1", "image": "img",
200			"batchSize": 3, "firstBatchSize": 1,
201			"include": [{"env": "prod"}],
202			"exclude": [{"quarantine": "true"}],
203			"clusters": [
204				{"id": "c1", "tags": {"env": "prod"}},
205				{"id": "c2", "tags": {"env": "prod", "quarantine": "true"}},
206				{"id": "c3", "disabled": true, "tags": {"env": "prod"}},
207				{"id": "c4", "tags": {"env": "dev"}},
208				{"id": "c5", "tags": {"env": "prod"}}
209			]
210		}`)
211		plan, err := MakeReleasePlan(in)
212		if err != nil {
213			t.Fatal(err)
214		}
215		if got := batchIDs(plan); strings.Join(got, "|") != "c1|c5" {
216			t.Fatalf("batches = %v, want [c1]|[c5]", got)
217		}
218		wantExcluded := []ExcludedCluster{
219			{ID: "c2", Reason: ReasonExcludeMatched},
220			{ID: "c3", Reason: ReasonDisabled},
221			{ID: "c4", Reason: ReasonIncludeNotMatched},
222		}
223		if !reflect.DeepEqual(plan.Excluded, wantExcluded) {
224			t.Fatalf("excluded = %+v, want %+v", plan.Excluded, wantExcluded)
225		}
226	}
227	
228	// TestParse_FirstBatchSizeInvalid: every illegal JSON value for the optional
229	// field is rejected with an error naming the field and the reason — never
230	// ignored, rounded, truncated or clamped — and the returned config is the
231	// zero value. An explicit zero is rejected just like any non-positive value.
232	func TestParse_FirstBatchSizeInvalid(t *testing.T) {
233		clusters := `{"id":"c1"}`
234		cases := map[string]struct {
235			literal string
236			wantErr string
237		}{
238			"explicit zero":     {"0", `字段 "firstBatchSize" 必须是正整数`},
239			"negative":          {"-2", `字段 "firstBatchSize" 必须是正整数`},
240			"fraction":          {"2.5", `字段 "firstBatchSize" 必须是正整数`},
241			"string":            {`"2"`, `字段 "firstBatchSize" 必须是正整数`},
242			"boolean":           {"true", `字段 "firstBatchSize" 必须是正整数`},
243			"null":              {"null", `字段 "firstBatchSize" 必须是正整数`},
244			"overflow":          {"9223372036854775808", `字段 "firstBatchSize" 必须是正整数`},
245			"larger than batch": {"3", `字段 "firstBatchSize" 不能大于 "batchSize"`},
246		}
247		for name, tc := range cases {
248			t.Run(name, func(t *testing.T) {
249				in, err := ParseReleaseInput([]byte(firstBatchDoc(2, tc.literal, clusters)))
250				if err == nil {
251					t.Fatalf("firstBatchSize %s must be rejected, got %+v", tc.literal, in)
252				}
253				if err.Error() != tc.wantErr {
254					t.Fatalf("error = %q, want %q", err.Error(), tc.wantErr)
255				}
256				if !reflect.DeepEqual(in, ReleasePlanInput{}) {
257					t.Fatalf("rejected parse must return the zero-value config, got %+v", in)
258				}
259			})
260		}
261	}
262	
263	// TestValidate_FirstBatchSizeGoConfig: a directly constructed Go config uses
264	// the zero value as "unset"; every other illegal value is rejected before
265	// planning by both ValidateReleaseInput and MakeReleasePlan, the latter
266	// returning the zero-value plan.
267	func TestValidate_FirstBatchSizeGoConfig(t *testing.T) {
268		valid := ReleasePlanInput{
269			App: "app", Revision: "r1", Image: "img", BatchSize: 2,
270			Clusters: []Cluster{{ID: "c1"}, {ID: "c2"}, {ID: "c3"}},
271		}
272	
273		// Zero means unset and plans with the original batching.
274		plan, err := MakeReleasePlan(valid)
275		if err != nil {
276			t.Fatalf("zero firstBatchSize must be legal (unset): %v", err)
277		}
278		if got := batchIDs(plan); strings.Join(got, "|") != "c1,c2|c3" {
279			t.Fatalf("batches = %v, want [c1 c2]|[c3]", got)
280		}
281	
282		cases := map[string]struct {
283			first   int
284			wantErr string
285		}{
286			"negative":          {-1, `字段 "firstBatchSize" 必须是正整数`},
287			"larger than batch": {3, `字段 "firstBatchSize" 不能大于 "batchSize"`},
288		}
289		for name, tc := range cases {
290			t.Run(name, func(t *testing.T) {
291				in := valid
292				in.FirstBatchSize = tc.first
293				if verr := ValidateReleaseInput(in); verr == nil || verr.Error() != tc.wantErr {
294					t.Fatalf("ValidateReleaseInput = %v, want %q", verr, tc.wantErr)
295				}
296				plan, perr := MakeReleasePlan(in)
297				if perr == nil || perr.Error() != tc.wantErr {
298					t.Fatalf("MakeReleasePlan err = %v, want %q", perr, tc.wantErr)
299				}
300				assertZeroReleasePlan(t, plan)
301			})
302		}
303	}
304	
305	// TestPlan_FirstBatchKeepsExistingFailures: the first-batch cap never masks
306	// the established planning failures — all candidates filtered out still
307	// reports every candidate's reason, and a selected cluster missing the
308	// spreadBy tag still fails the whole plan with the zero-value plan.
309	func TestPlan_FirstBatchKeepsExistingFailures(t *testing.T) {
310		allRejected := parsePlan(t, `{
311			"app": "app", "revision": "r1", "image": "img",
312			"batchSize": 3, "firstBatchSize": 1,
313			"include": [{"env": "staging"}],
314			"clusters": [{"id": "b"}, {"id": "a", "disabled": true}]
315		}`)
316		plan, err := MakeReleasePlan(allRejected)
317		if err == nil {
318			t.Fatal("all candidates filtered out must still fail")
319		}
320		assertZeroReleasePlan(t, plan)
321		want := allRejectedLibraryError("a："+ReasonDisabled, "b："+ReasonIncludeNotMatched)
322		if err.Error() != want {
323			t.Fatalf("error = %q, want %q", err.Error(), want)
324		}
325	
326		missingTag := parsePlan(t, `{
327			"app": "app", "revision": "r1", "image": "img",
328			"batchSize": 3, "firstBatchSize": 1, "spreadBy": "zone",
329			"clusters": [
330				{"id": "c1", "tags": {"zone": "east"}},
331				{"id": "c2"}
332			]
333		}`)
334		plan, err = MakeReleasePlan(missingTag)
335		if err == nil {
336			t.Fatal("a selected cluster missing the spread tag must still fail")
337		}
338		assertZeroReleasePlan(t, plan)
339		if err.Error() != `集群 "c2" 缺少故障域标签 "zone"` {
340			t.Fatalf("error = %q, want the missing-tag failure", err.Error())
341		}
342	}
343	
344	// TestPlanCLI_FirstBatchFullPlan drives the setting through the command line:
345	// the config file entry is the only interface, success exits 0 with the
346	// complete plan on stdout and an empty stderr.
347	func TestPlanCLI_FirstBatchFullPlan(t *testing.T) {
348		doc := `{
349		  "app": "payments",
350		  "revision": "2026.10.0-r3",
351		  "image": "registry.example.net/payments:2026.10.0-r3",
352		  "batchSize": 3,
353		  "firstBatchSize": 2,
354		  "spreadBy": "zone",
355		  "clusters": [
356		    {"id": "a", "tags": {"zone": "east"}},
357		    {"id": "b", "tags": {"zone": "east"}},
358		    {"id": "c", "tags": {"zone": "west"}},
359		    {"id": "d", "tags": {"zone": "north"}},
360		    {"id": "e", "tags": {"zone": "west"}}
361		  ]
362		}`
363		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
364		if code != 0 {
365			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
366		}
367		if stderr != "" {
368			t.Fatalf("expected empty stderr on success, got %q", stderr)
369		}
370		p := decodeCLIPlan(t, stdout)
371		domains := map[string]string{
372			"a": "east", "b": "east", "c": "west", "d": "north", "e": "west",
373		}
374		// Batch 1 is capped at 2; batch 2 runs at the full capacity 3 again.
375		assertSpreadBatches(t, p, [][]string{{"a", "c"}, {"b", "d", "e"}}, domains, 3)
376	}
377	
378	// TestPlanCLI_FirstBatchInvalidFailsCleanly: an illegal firstBatchSize in the
379	// config file exits 1, explains the field and the reason on stderr, and
380	// leaves stdout completely empty.
381	func TestPlanCLI_FirstBatchInvalidFailsCleanly(t *testing.T) {
382		cases := map[string]struct {
383			literal string
384			wantErr string
385		}{
386			"zero":              {"0", `字段 "firstBatchSize" 必须是正整数`},
