312	// as a JSON format error.
313	func TestParse_HugeCapacityOutOfRangeStillRejected(t *testing.T) {
314		literals := []string{
315			"9223372036854775808",          // beyond int64 on every supported environment
316			strconv.Itoa(testMaxInt) + "0", // one digit past the native max int
317		}
