329				}
330				if strings.Contains(err.Error(), "JSON 格式错误") {
331					t.Fatalf("out-of-range integer is legal JSON, not a format error: %v", err)
332				}
333				if !reflect.DeepEqual(in, ReleasePlanInput{}) {
334					t.Fatalf("rejected parse must return the zero-value config, got %+v", in)
335				}
336	
337				// CLI: exit 1, empty stdout, the field error on stderr.
338				code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
339				if code != 1 {
340					t.Fatalf("expected exit 1, got %d; stdout=%q stderr=%q", code, stdout, stderr)
341				}
342				if stdout != "" {
343					t.Fatalf("stdout must be empty on rejection, got %q", stdout)
344				}
345				if !strings.Contains(stderr, wantErr) {
346					t.Fatalf("stderr = %q, want it to contain %q", stderr, wantErr)
347				}
348				if strings.Contains(stderr, "JSON 格式错误") {
349					t.Fatalf("stderr must not call a legal JSON number malformed: %q", stderr)
350				}
351			})
352		}
353	}
